/bin/bash -lc "git status --short && printf '\\n--- all tracked/unignored files ---\\n' && git ls-files && printf '\\n--- runtime checks ---\\n' && npm test && node --input-type=module - <<'NODE'
import { requestedFile } from './src/files.js';
for (const name of ['report.txt','../../etc/passwd','/etc/passwd','']) {
  try { console.log(JSON.stringify(name), '=>', requestedFile(name)); }
  catch (e) { console.log(JSON.stringify(name), 'THROWS', e.name, e.message); }
}
NODE
printf '\\n--- line-numbered sources ---\\n' && nl -ba src/server.js && nl -ba src/files.js && nl -ba migrations/003_remove_audit.sql"

